/**
 * Generate the Linux installer's shell string table from the five-language catalog.
 *
 * [Why a generated file and not literals in the wizard] The wizard is a bash script; its copy
 * lives in the same catalog as the NSIS and macOS pkg installers. Hand-writing a second copy
 * would put the same words in a place with no test at all, and a missing translation would show
 * up as a blank label on somebody's desktop. The catalog gate already refuses a key that is
 * missing or blank in one of the five languages; this generator is what turns that guarantee
 * into something bash can read.
 *
 * [Why one file per build, like the NSIS fragment] `installer_strings.nsh` is generated the
 * same way and checked by scripts/checks/check-product-consistency.ps1. A generated table plus
 * a --check run in the static gates is the only way "add a language" stays a one-place edit.
 *
 * Usage:
 *   node scripts/release/build-linux-installer-strings.mjs           # generate
 *   node scripts/release/build-linux-installer-strings.mjs --check   # verify it is current
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { collectInstallerStrings, KEY_PREFIX, LINUX_KEY_PREFIX } from "./catalog.mjs";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const outputPath = join(scriptDir, "linux-installer", "strings.sh");

/** `zh-CN` -> `zh_CN`: the suffix of the bash associative array. */
function shellLocale(locale) {
    return locale.replace(/-/g, "_");
}

/**
 * Escape one value into a bash single-quoted string.
 *
 * [Per-character and only for the quote] Single quotes cannot be escaped inside a single-quoted
 * string at all; the one portable spelling is leaving the quote, writing \', and entering again.
 * Doing it by replacement rather than by a general escaper keeps newlines, backslashes and the
 * dollar sign exactly as translated -- a second escaping layer here would turn a legitimate
 * backslash in a path into something else.
 */
function bashQuote(text) {
    return "'" + text.replace(/'/g, "'\\''") + "'";
}

function render({ keys, catalogs }) {
    const lines = [
        "#!/usr/bin/env bash",
        "# Generated by scripts/release/build-linux-installer-strings.mjs — do not edit by hand.",
        "#",
        "# The Linux wizard's copy, generated from the same five-language catalog the NSIS installer",
        "# and the macOS pkg read (frontend/src/i18n/*.ts, entries prefixed " +
            LINUX_KEY_PREFIX +
            ").",
        "# Regenerating is part of the build; scripts/checks/check-product-consistency.ps1 fails when",
        "# this file is stale.",
        "",
        `# Languages: ${catalogs.map(({ locale }) => locale).join(", ")}`,
        `# Entries: ${keys.length} × ${catalogs.length} languages`,
        "",
        "# Every locale the wizard offers. The first entry is the fallback for an unknown LANG.",
        `HFS_I18N_LOCALES=(${catalogs.map(({ locale }) => locale).join(" ")})`,
        "",
    ];

    for (const { locale, catalog } of catalogs) {
        lines.push(`declare -A HFS_I18N_${shellLocale(locale)}=(`);
        for (const key of keys) {
            const short = key.slice(LINUX_KEY_PREFIX.length);
            lines.push(`    [${short}]=${bashQuote(catalog[key])}`);
        }
        lines.push(")", "");
    }

    return lines.join("\n");
}

async function main() {
    const checkOnly = process.argv.includes("--check");
    const { keys, catalogs } = await collectInstallerStrings();
    const linuxKeys = keys.filter((key) => key.startsWith(LINUX_KEY_PREFIX));
    if (linuxKeys.length === 0) {
        throw new Error(
            `no ${LINUX_KEY_PREFIX}-prefixed keys found; the wizard would have no copy`,
        );
    }
    const rendered = render({ keys: linuxKeys, catalogs });

    if (checkOnly) {
        const current = existsSync(outputPath) ? readFileSync(outputPath, "utf8") : null;
        if (current !== rendered) {
            throw new Error(
                `${outputPath} is stale; run: node scripts/release/build-linux-installer-strings.mjs`,
            );
        }
        console.log("linux installer strings are up to date");
        return;
    }

    mkdirSync(dirname(outputPath), { recursive: true });
    writeFileSync(outputPath, rendered, "utf8");
    console.log(`wrote ${outputPath} (${linuxKeys.length} keys × ${catalogs.length} languages)`);
}

main().catch((error) => {
    console.error(`build-linux-installer-strings: ${error.message}`);
    process.exit(1);
});
